// scaffold_app v3 (2026-05-20) — AppSummary now embeds its own recent-changes table; RC module removed.
// scaffold_app v2 (2026-05-08) — minimal app registration per LLD V2.
// Form only collects: appName, apiBaseUrl. Default scope, knobs, conditions
// are now collected per-page (in AppSummary's create-page form), not per-app.

const WORKSPACE_ID = constants.WS;
const BASE = window.location.origin;
const h = { 'Content-Type': 'application/json', 'Tj-Workspace-Id': WORKSPACE_ID };
const UTIL_TABLE = constants.UTIL_TABLE;

// COC AppSummary module (the correct one with v2 form fields).
// Old "test-sso-write" module 4f88ceab/624a8ee4 was deprecated.
const SUMMARY_MODULE_APP_ID = constants.SUMMARY_MODULE_APP_ID;
const SUMMARY_MODULE_VER_ID = constants.SUMMARY_MODULE_VER_ID;
const ENV_ID = constants.ENV_ID;

const appName    = components.ModalAppName.value?.trim();
const apiBaseUrl = components.ModalApiBaseUrl.value?.trim();
if (!appName || !apiBaseUrl) {
  await actions.showAlert('danger', 'App name and API base URL are required');
  throw new Error('App name and API base URL are required');
}

// 1. Insert config_apps (using existing config_utility table — repurposed per architecture spec)
const utilUuid = crypto.randomUUID();
const insertR = await fetch(`${BASE}/api/tooljet-db/proxy/${UTIL_TABLE}`, {
  method: 'POST', credentials: 'include',
  headers: { ...h, 'Prefer': 'return=representation' },
  body: JSON.stringify({
    uuid: utilUuid,
    name: appName,
    type: 'domestic',          // matches parent homepage type (COC Domestic)
    api_base_url: apiBaseUrl,
    created_at: new Date().toISOString()
  })
});
if (!insertR.ok) {
  const t = await insertR.text();
  let msg = 'DB insert failed';
  try { const j = JSON.parse(t); msg = Array.isArray(j.message) ? j.message.join(', ') : (j.message || msg); } catch {}
  await actions.showAlert('danger', msg);
  throw new Error(msg);
}
const [row] = await insertR.json();

// 2. Create TJ app
const appR = await fetch(`${BASE}/api/apps`, {
  method: 'POST', credentials: 'include', headers: h,
  body: JSON.stringify({ name: appName, icon: 'code', type: 'front-end' })
});
if (!appR.ok) {
  await fetch(`${BASE}/api/tooljet-db/proxy/${UTIL_TABLE}?id=eq.${row.id}`, {
    method: 'DELETE', credentials: 'include', headers: h
  });
  const t = await appR.text();
  let msg = 'Failed to create app';
  try { const j = JSON.parse(t); msg = Array.isArray(j.message) ? j.message.join(', ') : (j.message || msg); } catch {}
  await actions.showAlert('danger', msg);
  throw new Error(msg);
}
const app = await appR.json();
const tjAppId = app.id;

// 2b. Force is_public=false
try {
  await fetch(`${BASE}/api/apps/${tjAppId}`, {
    method: 'PUT', credentials: 'include', headers: h,
    body: JSON.stringify({ app: { is_public: false } })
  });
} catch (e) { /* non-fatal */ }

// 3. Fetch app to get real version + page IDs
const appDetailR = await fetch(`${BASE}/api/apps/${tjAppId}`, {
  credentials: 'include', headers: h
});
const appDetail = await appDetailR.json();
const versionId = appDetail.editing_version?.id;
const pageId    = appDetail.pages?.[0]?.id;

// 4. Rename page to Summary (handle = 'summary')
if (pageId) {
  await fetch(`${BASE}/api/v2/apps/${tjAppId}/versions/${versionId}/pages`, {
    method: 'PUT', credentials: 'include', headers: h,
    body: JSON.stringify({ pageId, diff: { name: 'Summary' } })
  });
  await fetch(`${BASE}/api/v2/apps/${tjAppId}/versions/${versionId}/pages`, {
    method: 'PUT', credentials: 'include', headers: h,
    body: JSON.stringify({ pageId, diff: { handle: 'summary' } })
  });
}

// 5. Patch tj_app_id back onto the config_apps row
await fetch(`${BASE}/api/tooljet-db/proxy/${UTIL_TABLE}?id=eq.${row.id}`, {
  method: 'PATCH', credentials: 'include', headers: h,
  body: JSON.stringify({ tj_app_id: tjAppId })
});

// 6. Wire AppSummary module onto the Summary page
function uid() {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, c => {
    const r = Math.random() * 16 | 0;
    return (c === 'x' ? r : (r & 0x3 | 0x8)).toString(16);
  });
}

const moduleCompId = uid();
const modProps = {
  moduleAppId:         { value: SUMMARY_MODULE_APP_ID },
  moduleVersionId:     { value: SUMMARY_MODULE_VER_ID },
  moduleEnvironmentId: { value: ENV_ID },
  visibility:          { value: true },
  tj_app_id:           { value: tjAppId }
};

await fetch(`${BASE}/api/v2/apps/${tjAppId}/versions/${versionId}/components`, {
  method: 'POST', credentials: 'include', headers: h,
  body: JSON.stringify({
    is_user_switched_version: false,
    pageId,
    diff: {
      [moduleCompId]: {
        name: 'AppSummaryModule',
        type: 'ModuleViewer',
        component: {
          name: 'AppSummaryModule',
          component: 'ModuleViewer',
          definition: { properties: modProps, styles: {}, others: {} }
        },
        properties: modProps,
        layouts: {
          desktop: { top: 0, left: 0, width: 43, height: 740 },
          mobile:  { top: 0, left: 0, width: 43, height: 210 }
        },
        parent: null
      }
    }
  })
});

// 7. RecentChangesModule mount removed — AppSummary now embeds its own
// recent-changes table + rollback preview inline. (2026-05-20)

// 8. JWT minting (LFCE-4726 / LFCE-5144)
// Provision the token queries at app creation, so the app has a signed token
// from the moment it is opened - before any page is scaffolded, and covering
// REST queries added by hand later. scaffold_page creates the same two queries
// and guards on existingMap, so having both paths is safe and idempotent.
//
// Wrapped in try/catch deliberately: a minting failure must never abort app
// creation. Without the token, variables.enrichedJwt stays empty, the
// Authorization header resolves to '' and is omitted, and pages fall back to
// the legacy X-CoC-Actor-* headers exactly as they do today.
//
// The key is chosen per host via the jwt_host_domains table, so an app
// pointed at a service with no entry mints nothing and keeps using the
// legacy headers.
try {
  const RUNJS_DS = constants.RUNJS_DS || 'e39dea47-4785-4900-a2a4-6f41287b9f3f';
  const PERM_DS  = constants.PERMISSION_DS || '4f89136c-b5b1-4c37-997d-4a138496c869';

  const _addQ = async (dsId, name, kind, options) => {
    const r = await fetch(`${BASE}/api/data-queries/data-sources/${dsId}/versions/${versionId}`, {
      method: 'POST', credentials: 'include', headers: h,
      body: JSON.stringify({ name, kind, options })
    });
    if (!r.ok) throw new Error(`addQuery ${name} failed: ${await r.text()}`);
    return (await r.json()).id;
  };

  // Identity comes from the Tooljet session, never from page state.
  await _addQ(PERM_DS, 'jwtmaker-pgsql', 'postgresql', {
    mode: 'sql',
    method: 'get',
    query: [
        "-- Mint a CoC token for whichever service this app talks to. Nothing here is",
        "-- service-specific: the secret's name is BUILT at runtime, so onboarding a",
        "-- new service never touches this SQL.",
        "--",
        "--   1. host   <- config_apps.api_base_url for this app, reduced to a hostname",
        "--   2. domain <- jwt_host_domains, which also carries the `enabled` switch",
        "--   3. key    <- permission._secrets, row named 'coc_jwt_' || host",
        "--",
        "-- The host comes from config_apps, not variables.api_base_url, on purpose:",
        "-- that variable is set by scaffold_page's init code, so an app with no page",
        "-- scaffolded yet never has it, and even when present that init races",
        "-- mintJwt's runOnPageLoad. Reading config_apps server-side fixes both and",
        "-- means the host cannot be altered from the browser.",
        "--",
        "-- To onboard a service: add its host+domain row (ToolJet DB UI, no code",
        "-- change) and insert coc_jwt_<DOMAIN> into permission._secrets. Nothing else.",
        "--",
        "-- NULL when the host is unknown, the row is disabled, or no key is stored;",
        "-- the app then omits Authorization and falls back to the legacy",
        "-- X-CoC-Actor-* headers. An enrolled service rejects a bad token with 401",
        "-- and never falls back, so a wrong token is worse than none.",
        "WITH h AS (",
        "  SELECT split_part(split_part(api_base_url, '://', 2), '/', 1) AS host",
        "  FROM \"workspace_{{constants.WS}}\".\"{{constants.UTIL_TABLE}}\"",
        "  WHERE tj_app_id = '{{variables.tj_app_id}}'",
        "  LIMIT 1",
        "), k AS (",
        "  SELECT nullif(btrim(value), '') AS key",
        "  FROM permission._secrets",
        "  WHERE name = 'coc_jwt_' || (SELECT host FROM h)",
        "  LIMIT 1",
        ")",
        "SELECT CASE WHEN (SELECT key FROM k) IS NULL THEN NULL",
        "            ELSE permission.mint_jwt('{{globals.currentUser.email}}',",
        "                                     (SELECT key FROM k),",
        "                                     '{{constants.WS}}'::uuid)",
        "       END AS jwt;"
      ].join('\n')
  });

  // runOnPageLoad, plus refresh on an interval and on tab focus - tokens live
  // one hour, so a tab left open would otherwise start failing every call.
  await _addQ(RUNJS_DS, 'mintJwt', 'runjs', {
    runOnPageLoad: true,
    code: [
      "const _REFRESH_MS = 40 * 60 * 1000;",
      "const _STALE_S = 300;",
      "let _cocExp = 0;",
      "",
      "async function _cocMint() {",
      "  try {",
      "    const _appId = (window.location.pathname.match(/(?:apps|applications)\\/([0-9a-f-]{36})/) || [])[1] || '';",
      "    if (!_appId) { console.warn('[mintJwt] could not read app id from URL'); return false; }",
      "    await actions.setVariable('tj_app_id', _appId);",
      "    const resp = await queries['jwtmaker-pgsql'].run();",
      "    const jwt = (resp && resp.data && resp.data[0] && resp.data[0].jwt)",
      "      || queries['jwtmaker-pgsql']?.data?.[0]?.jwt;",
      "    if (!jwt) { console.warn('[mintJwt] no token for ' + (globals.currentUser && globals.currentUser.email)); return false; }",
      "    await actions.setVariable('enrichedJwt', jwt);",
      "    try {",
      "      const seg = jwt.split('.')[1];",
      "      _cocExp = JSON.parse(atob(seg.replace(/-/g,'+').replace(/_/g,'/'))).exp || 0;",
      "    } catch (e) { _cocExp = 0; }",
      "    return true;",
      "  } catch (e) {",
      "    console.error('[mintJwt] failed', e);",
      "    return false;",
      "  }",
      "}",
      "",
      "await _cocMint();",
      "",
      "window.__cocJwtMint = _cocMint;",
      "window.__cocJwtStale = function () {",
      "  return !_cocExp || (_cocExp - Math.floor(Date.now() / 1000)) < _STALE_S;",
      "};",
      "",
      "if (!window.__cocJwtRefreshInstalled) {",
      "  window.__cocJwtRefreshInstalled = true;",
      "  setInterval(function () { if (window.__cocJwtMint) window.__cocJwtMint(); }, _REFRESH_MS);",
      "  document.addEventListener('visibilitychange', function () {",
      "    if (document.visibilityState !== 'visible') return;",
      "    if (window.__cocJwtStale && window.__cocJwtStale() && window.__cocJwtMint) window.__cocJwtMint();",
      "  });",
      "  console.log('[mintJwt] refresh installed');",
      "}"
    ].join('\n')
  });
} catch (e) {
  console.warn('[scaffold_app] JWT minting not provisioned; pages will use legacy headers', e);
}

return { success: true, utilityId: row.id, utilityUuid: utilUuid, tjAppId, versionId, summaryPageId: pageId };
